/**
 * Type-safe API client derived from the generated OpenAPI schema.
 *
 * `schema.d.ts` is generated by `npm run generate:api` from `api/openapi.yaml`
 * and must never be edited by hand. This module turns the generated `paths`
 * map into a small client whose URLs, query parameters, request bodies and
 * responses are all checked against the specification, so a backend route that
 * drifts from the spec breaks the frontend build.
 */
import type { paths } from './schema';

/** Every path documented in the OpenAPI specification. */
export type ApiPath = keyof paths;

type PathsWith<M extends string> = {
  [P in ApiPath]: paths[P] extends Record<M, unknown>
    ? paths[P][M] extends undefined
      ? never
      : P
    : never;
}[ApiPath];

export type GetPath = PathsWith<'get'>;
export type PostPath = PathsWith<'post'>;
export type PatchPath = PathsWith<'patch'>;
export type PutPath = PathsWith<'put'>;
export type DeletePath = PathsWith<'delete'>;

type Operation<P extends ApiPath, M extends string> =
  paths[P] extends Record<M, infer O> ? O : never;

type QueryOf<P extends ApiPath, M extends string> =
  Operation<P, M> extends { parameters: { query?: infer Q } } ? Q : never;

type PathParamsOf<P extends ApiPath, M extends string> =
  Operation<P, M> extends { parameters: { path: infer Params } } ? Params : never;

type BodyOf<P extends ApiPath, M extends string> =
  Operation<P, M> extends { requestBody?: { content: { 'application/json': infer B } } }
    ? B
    : never;

type JsonResponses<P extends ApiPath, M extends string> =
  Operation<P, M> extends { responses: infer R }
    ? R[keyof R & (200 | 201 | 202)] extends { content: { 'application/json': infer T } }
      ? T
      : never
    : never;

/** Successful JSON response body of an operation, or `void` when there is none. */
export type ResponseOf<P extends ApiPath, M extends string> = [JsonResponses<P, M>] extends [never]
  ? void
  : JsonResponses<P, M>;

export interface RequestOptions<P extends ApiPath, M extends string> {
  /** Values for the `{...}` placeholders in the path template. */
  params?: PathParamsOf<P, M>;
  /** Query string parameters as documented in the specification. */
  query?: QueryOf<P, M>;
  /** JSON request body. */
  body?: BodyOf<P, M>;
  signal?: AbortSignal;
  headers?: Record<string, string>;
}

/** Performs the raw HTTP call; injected so the client stays testable. */
export type Transport = (url: string, init: RequestInit) => Promise<unknown>;

export function buildQuery(query: unknown): string {
  if (!query || typeof query !== 'object') {
    return '';
  }
  const search = new URLSearchParams();
  Object.entries(query as Record<string, unknown>).forEach(([key, value]) => {
    if (value === undefined || value === null || value === '') {
      return;
    }
    search.set(key, String(value));
  });
  const rendered = search.toString();
  return rendered ? `?${rendered}` : '';
}

export function renderPath(template: string, params?: unknown): string {
  if (!params || typeof params !== 'object') {
    return template;
  }
  return template.replace(/\{(\w+)\}/g, (_match, name: string) => {
    const value = (params as Record<string, unknown>)[name];
    if (value === undefined || value === null) {
      throw new Error(`missing path parameter "${name}" for ${template}`);
    }
    return encodeURIComponent(String(value));
  });
}

/**
 * Creates a client bound to a transport. `transport` receives the fully
 * rendered URL (including the `/api/v1` prefix as documented in the spec).
 */
export function createApiClient(transport: Transport) {
  function request<P extends ApiPath, M extends string>(
    method: M,
    path: P,
    options?: RequestOptions<P, M>,
  ): Promise<ResponseOf<P, M>> {
    const url = renderPath(path as string, options?.params) + buildQuery(options?.query);
    const init: RequestInit = {
      method: method.toUpperCase(),
      signal: options?.signal,
      headers: options?.headers,
    };
    if (options?.body !== undefined) {
      init.body = JSON.stringify(options.body);
    }
    return transport(url, init) as Promise<ResponseOf<P, M>>;
  }

  return {
    request,
    get: <P extends GetPath>(path: P, options?: RequestOptions<P, 'get'>) =>
      request('get', path, options),
    post: <P extends PostPath>(path: P, options?: RequestOptions<P, 'post'>) =>
      request('post', path, options),
    patch: <P extends PatchPath>(path: P, options?: RequestOptions<P, 'patch'>) =>
      request('patch', path, options),
    put: <P extends PutPath>(path: P, options?: RequestOptions<P, 'put'>) =>
      request('put', path, options),
    delete: <P extends DeletePath>(path: P, options?: RequestOptions<P, 'delete'>) =>
      request('delete', path, options),
  };
}

export type ApiClient = ReturnType<typeof createApiClient>;
